package com.mavric.health.persistence.sqlserver;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.security.core.context.SecurityContextHolder;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.ApiException;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Contract tests with executor double and modeled transactions; no connected schedule/permissions. */
class SqlServerSchedulingStoreTest {
 static final String ID="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",APPOINTMENT="cc000000-0000-4000-8000-000000000001",OTHER="dd000000-0000-4000-8000-000000000001";
 static final Instant FROM=Instant.parse("2026-11-05T00:00:00.123456Z"),TO=FROM.plusSeconds(86400);
 final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final SqlServerSchedulingStore store=new SqlServerSchedulingStore(executor,manager);final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/appointments");final Deque<SqlServerExecutor.Result> results=new ArrayDeque<>();final List<SqlServerProcedure> calls=new ArrayList<>();final List<List<Object>> args=new ArrayList<>();
 SqlServerSchedulingStoreTest(){actor("REC");when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(ID,c.actorId());assertEquals(TENANT,c.tenantId());assertEquals("a".repeat(64),c.tokenHash());calls.add(inv.getArgument(0));args.add(Arrays.asList(((Object[])inv.getRawArguments()[2]).clone()));return results.removeFirst();});}
 void actor(String role){request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",TENANT,List.of(role),"a".repeat(64)));request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","SUSPENDED",List.of()));}
 static Map<String,Object> appointment(){var r=new LinkedHashMap<String,Object>();r.put("id",APPOINTMENT);r.put("tenantId",TENANT);r.put("patientId",OTHER);r.put("branchId",ID);r.put("professionalId",ID);r.put("specialtyCode","H_FAMILY");r.put("startsAt",FROM.toString());r.put("endsAt",FROM.plusSeconds(1800).toString());r.put("status","RESERVED");r.put("service","Synthetic \u4e2d\uD83E\uDDB7");r.put("note","Synthetic note \u4e2d\uD83E\uDDB7".repeat(25));r.put("revision",1);r.put("requestKey","synthetic-key-001");r.put("requestHash",com.mavric.health.shared.Checks.hash("synthetic-request"));return r;}
 void rows(List<Map<String,Object>> rows){results.add(new SqlServerExecutor.Result(List.of(rows),List.of(0)));}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 static void safe(Runnable work){var e=assertThrows(ApiException.class,work::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertNull(e.getCause());}
 @Test void exactDescriptorsInstantBindsExplicitNullAndProjection14(){var row=appointment();row.put("passwordHash","private");rows(List.of(row));var list=store.list(request,FROM,TO,null);assertEquals(14,list.getFirst().size());assertEquals(Arrays.asList(FROM,TO,null),args.getFirst());assertSame(FROM,args.getFirst().getFirst());assertInstanceOf(Instant.class,args.getFirst().getFirst());assertFalse(list.toString().contains("private"));assertEquals(row.get("note"),list.getFirst().get("note"));assertEquals(row.get("requestHash"),list.getFirst().get("requestHash"));assertThrows(UnsupportedOperationException.class,list::clear);assertThrows(UnsupportedOperationException.class,list.getFirst()::clear);row=appointment();row.put("branchId",OTHER);rows(List.of(row));assertEquals(OTHER,store.get(request,APPOINTMENT).get("branchId"));assertEquals(List.of(APPOINTMENT),args.getLast());assertEquals(List.of(SqlServerProcedure.APPOINTMENTS_LIST,SqlServerProcedure.APPOINTMENT_GET),calls);}
 @Test void localDurationDaysRuleAccepts93Days23hAndRejects94WithoutTruncation(){rows(List.of());Instant end=FROM.plus(Duration.ofDays(93)).plus(Duration.ofHours(23)).plusSeconds(59);store.list(request,FROM,end,null);assertEquals(end,args.getFirst().get(1));assertEquals(400,assertThrows(ApiException.class,()->store.list(request,FROM,FROM.plus(Duration.ofDays(94)),null)).status);assertEquals(1,calls.size());}
 @Test void nullPrecisionSqlRangeWindowAndBranchInvalidBeforeExecutor(){for(Instant from:Arrays.asList(null,FROM.plusNanos(1),Instant.parse("0000-12-31T23:59:59Z"),Instant.parse("+10000-01-01T00:00:00Z")))assertEquals(400,assertThrows(ApiException.class,()->store.list(request,from,TO,null)).status);for(Instant to:Arrays.asList(null,TO.plusNanos(1),FROM,FROM.minusSeconds(1),Instant.parse("+10000-01-01T00:00:00Z")))assertEquals(400,assertThrows(ApiException.class,()->store.list(request,FROM,to,null)).status);assertEquals(400,assertThrows(ApiException.class,()->store.list(request,FROM,TO,"bad")).status);assertEquals(400,assertThrows(ApiException.class,()->store.get(request,"bad")).status);verifyNoInteractions(executor);}
 @Test void exactSqlDatetimeBoundsArePassedAsInstantNotTimestamp(){Instant minimum=Instant.parse("0001-01-01T00:00:00Z"),maximum=Instant.parse("9999-12-31T23:59:59.999999Z");rows(List.of());store.list(request,minimum,minimum.plusSeconds(1),null);rows(List.of());store.list(request,maximum.minusSeconds(1),maximum,null);assertEquals(minimum,args.getFirst().get(0));assertEquals(maximum,args.getLast().get(1));}
 @Test void listWindowAndBranchMismatchFailRatherThanFilterRows(){for(String start:List.of(FROM.minusNanos(1000).toString(),TO.toString())){var row=appointment();row.put("startsAt",start);row.put("endsAt",Instant.parse(start).plusSeconds(1800).toString());rows(List.of(row));safe(()->store.list(request,FROM,TO,null));}var row=appointment();row.put("branchId",OTHER);rows(List.of(row));safe(()->store.list(request,FROM,TO,ID));row=appointment();row.put("startsAt",TO.minusNanos(1000).toString());row.put("endsAt",TO.plusSeconds(1800).toString());rows(List.of(row));assertEquals(1,store.list(request,FROM,TO,ID).size());assertEquals(Arrays.asList(FROM,TO,ID),args.getLast());}
 @Test void everyColumnNullTypeEnumDateHashAndForeignIdAreRejected(){for(String key:appointment().keySet()){var row=appointment();row.remove(key);rows(List.of(row));safe(()->store.get(request,APPOINTMENT));row=appointment();row.put(key,null);rows(List.of(row));safe(()->store.get(request,APPOINTMENT));}for(var change:List.of(Map.entry("id",ID),Map.entry("tenantId",ID),Map.entry("patientId","bad"),Map.entry("professionalId","bad"),Map.entry("specialtyCode",1),Map.entry("revision",1L),Map.entry("revision",0),Map.entry("status","bad"),Map.entry("requestKey",1),Map.entry("requestHash","bad"),Map.entry("startsAt","2026-11-05T00:00:00.123456789Z"),Map.entry("startsAt","2026-11-05T00:00:00+00:00"),Map.entry("endsAt",FROM.toString()))){var row=appointment();row.put(change.getKey(),change.getValue());rows(List.of(row));safe(()->store.get(request,APPOINTMENT));}}
 @Test void validStatusesArePreservedWithoutJavaTransitionsAndGet404(){for(String status:List.of("REQUESTED","RESERVED","CONFIRMED","WAITING","CALLED","IN_CARE","COMPLETED","CANCELLED","WITHDRAWN")){var row=appointment();row.put("status",status);rows(List.of(row));assertEquals(status,store.get(request,APPOINTMENT).get("status"));}rows(List.of());assertEquals(404,assertThrows(ApiException.class,()->store.get(request,APPOINTMENT)).status);}
 @Test void resultSetsAndCardinalityLimitsAreExact(){rows(List.of());assertTrue(store.list(request,FROM,TO,null).isEmpty());rows(List.of(appointment(),appointment()));safe(()->store.get(request,APPOINTMENT));rows(Collections.nCopies(201,appointment()));safe(()->store.list(request,FROM,TO,null));var many=new ArrayList<Map<String,Object>>();for(int i=0;i<200;i++){var row=appointment();row.put("id",UUID.nameUUIDFromBytes(("synthetic-"+i).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString());row.put("requestKey","synthetic-key-"+i);row.put("startsAt",FROM.plusSeconds(i*1800L).toString());row.put("endsAt",FROM.plusSeconds((i+1)*1800L).toString());many.add(row);}rows(many);assertEquals(200,store.list(request,FROM,FROM.plusSeconds(200*1800L),null).size());results.add(new SqlServerExecutor.Result(List.of(),List.of()));safe(()->store.list(request,FROM,TO,null));results.add(new SqlServerExecutor.Result(List.of(List.of(),List.of()),List.of()));safe(()->store.get(request,APPOINTMENT));}
 @Test void directContextRolesUuidAndHashAreRevalidatedWithoutStateOrModuleGate(){for(String role:List.of("ADM","PAC","RES","SAD","SOP")){actor(role);assertEquals(403,assertThrows(ApiException.class,()->store.get(request,APPOINTMENT)).status);}actor("PRO");rows(List.of(appointment()));assertEquals(14,store.get(request,APPOINTMENT).size());request.setAttribute("health.actor",new Actor("bad","Synthetic","qa@example.test",TENANT,List.of("PRO"),"a".repeat(64)));safe(()->store.get(request,APPOINTMENT));request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",TENANT,List.of("PRO"),"bad"));safe(()->store.get(request,APPOINTMENT));request.setAttribute("health.tenant","bad");safe(()->store.get(request,APPOINTMENT));safe(()->store.get(null,APPOINTMENT));assertEquals(1,calls.size());}
 @Test void requiredMappingRollbackOuterJoinCommitAndVendorErrorsNeverRetry(){var bad=appointment();bad.put("revision",0);rows(List.of(bad));safe(()->store.get(request,APPOINTMENT));assertEquals("rollback",manager.events.getLast());rows(List.of(appointment()));manager.failCommit=true;safe(()->store.get(request,APPOINTMENT));rows(List.of(appointment()));assertThrows(RuntimeException.class,()->manager.outer(()->{store.get(request,APPOINTMENT);throw new RuntimeException("cancel");}));assertEquals("rollback",manager.events.getLast());for(int code:List.of(51001,51002)){doThrow(new RuntimeException(new java.sql.SQLException("private driver",null,code))).when(executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->store.get(request,APPOINTMENT));assertEquals(code==51001?403:404,e.status);assertFalse(e.toString().contains("private"));assertNull(e.getCause());}verify(executor,times(5)).execute(eq(SqlServerProcedure.APPOINTMENT_GET),any(),eq(APPOINTMENT));}
}
